-- Name: reconciliation_parameter(character varying); Type: FUNCTION; Schema: investory; Owner: -
--

CREATE FUNCTION investory.reconciliation_parameter(p_parameter_name character varying) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT numeric_value
    FROM investory.reconciliation_parameters
    WHERE parameter_name = p_parameter_name
$$;


--
-- Name: reconciliation_values_match(numeric, numeric); Type: FUNCTION; Schema: investory; Owner: -
--

CREATE FUNCTION investory.reconciliation_values_match(p_expected numeric, p_actual numeric) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT p_expected IS NOT NULL
       AND p_actual IS NOT NULL
       AND ABS(p_actual - p_expected)
           <= investory.reconciliation_effective_tolerance(p_expected, p_actual)
$$;


--
-- Name: FUNCTION reconciliation_values_match(p_expected numeric, p_actual numeric); Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON FUNCTION investory.reconciliation_values_match(p_expected numeric, p_actual numeric) IS 'Full-precision reconciliation comparison. NULL values never match.';


