--
-- Name: symbol_performance; Type: MATERIALIZED VIEW; Schema: investory; Owner: -
--

CREATE MATERIALIZED VIEW investory.symbol_performance AS
 WITH latest_positions AS (
         SELECT v.portfolio_id,
            v.asset_id,
                CASE
                    WHEN (count(*) FILTER (WHERE (NOT v.fx_rate_available)) > 0) THEN NULL::numeric
                    ELSE sum(v.unrealized_pl_in_base_currency)
                END AS unrealized_profit,
                CASE
                    WHEN (count(*) FILTER (WHERE (NOT v.fx_rate_available)) > 0) THEN NULL::numeric
                    ELSE sum(v.cost_basis_in_base_currency)
                END AS cost_basis,
                CASE
                    WHEN (count(*) FILTER (WHERE (NOT v.fx_rate_available)) > 0) THEN NULL::numeric
                    ELSE sum(v.market_value_in_base_currency)
                END AS market_value,
            count(*) FILTER (WHERE (NOT v.fx_rate_available)) AS missing_fx_count,
            (count(*) FILTER (WHERE (NOT v.fx_rate_available)) = 0) AS is_complete,
            sum(v.volume) AS total_volume
           FROM investory.v_open_position_values v
          GROUP BY v.portfolio_id, v.asset_id
        ), closed_position_components AS (
         SELECT a.portfolio_id,
            asset_1.id AS asset_id,
            p.profit_currency AS source_currency,
            pf.base_currency,
            (p.close_time)::date AS valuation_date,
            (COALESCE(p.profit, (0)::numeric) + COALESCE(p.swap, (0)::numeric)) AS amount_native
           FROM (((investory.positions p
             JOIN investory.accounts a ON ((a.id = p.account_id)))
             JOIN investory.portfolios pf ON ((pf.id = a.portfolio_id)))
             JOIN investory.assets asset_1 ON (((asset_1.id = p.asset_id) AND (asset_1.exclude_from_import = false))))
          WHERE ((p.close_time IS NOT NULL) AND (p.asset_id IS NOT NULL))
        UNION ALL
         SELECT a.portfolio_id,
            asset_1.id AS asset_id,
            p.commission_currency AS source_currency,
            pf.base_currency,
            (p.close_time)::date AS valuation_date,
            COALESCE(p.commission, (0)::numeric) AS amount_native
           FROM (((investory.positions p
             JOIN investory.accounts a ON ((a.id = p.account_id)))
             JOIN investory.portfolios pf ON ((pf.id = a.portfolio_id)))
             JOIN investory.assets asset_1 ON (((asset_1.id = p.asset_id) AND (asset_1.exclude_from_import = false))))
          WHERE ((p.close_time IS NOT NULL) AND (p.asset_id IS NOT NULL))
        ), closed_positions AS (
         SELECT cpr.portfolio_id,
            cpr.asset_id,
            sum(
                CASE
                    WHEN investory.fx_status_usable(fx.conversion_status) THEN (cpr.amount_native * fx.fx_rate_to_target)
                    ELSE NULL::numeric
                END) AS closed_profit,
            count(*) FILTER (WHERE (NOT investory.fx_status_usable(fx.conversion_status))) AS missing_fx_count,
            (count(*) FILTER (WHERE (NOT investory.fx_status_usable(fx.conversion_status))) = 0) AS is_complete
           FROM (closed_position_components cpr
             LEFT JOIN LATERAL investory.resolve_fx_rate(cpr.valuation_date, cpr.source_currency, cpr.base_currency) fx(source_currency, target_currency, fx_rate_to_target, source, rate_method, rate_source, source_rate_date, age_days, conversion_status) ON (true))
          GROUP BY cpr.portfolio_id, cpr.asset_id
        ), cash_dividends AS (
         SELECT a.portfolio_id,
            asset_1.id AS asset_id,
            sum(nco.amount_in_portfolio_base_currency) FILTER (WHERE ((nco.normalized_category)::text = ANY ((ARRAY['DIVIDEND'::character varying, 'DIVIDEND_REVERSAL'::character varying])::text[]))) AS dividends,
            sum((- nco.amount_in_portfolio_base_currency)) FILTER (WHERE ((nco.normalized_category)::text = ANY ((ARRAY['WITHHOLDING_TAX'::character varying, 'WITHHOLDING_TAX_REVERSAL'::character varying])::text[]))) AS withholding_tax,
            count(*) FILTER (WHERE (NOT investory.fx_status_usable(nco.portfolio_conversion_status))) AS missing_fx_count,
            (count(*) FILTER (WHERE (NOT investory.fx_status_usable(nco.portfolio_conversion_status))) = 0) AS is_complete
           FROM ((investory.normalized_cash_operations nco
             JOIN investory.accounts a ON ((a.id = nco.account_id)))
             JOIN investory.assets asset_1 ON (((asset_1.id = nco.asset_id) AND (asset_1.exclude_from_import = false))))
          GROUP BY a.portfolio_id, asset_1.id
        )
 SELECT COALESCE(lp.portfolio_id, cp.portfolio_id, cd.portfolio_id) AS portfolio_id,
    asset.symbol,
    asset.id AS asset_id,
        CASE
            WHEN COALESCE(cp.is_complete, true) THEN COALESCE(cp.closed_profit, (0)::numeric)
            ELSE NULL::numeric
        END AS closed_profit,
        CASE
            WHEN COALESCE(lp.is_complete, true) THEN COALESCE(lp.unrealized_profit, (0)::numeric)
            ELSE NULL::numeric
        END AS unrealized_profit,
        CASE
            WHEN (COALESCE(lp.is_complete, true) AND COALESCE(cp.is_complete, true) AND COALESCE(cd.is_complete, true)) THEN (((COALESCE(cp.closed_profit, (0)::numeric) + COALESCE(lp.unrealized_profit, (0)::numeric)) + COALESCE(cd.dividends, (0)::numeric)) - COALESCE(cd.withholding_tax, (0)::numeric))
            ELSE NULL::numeric
        END AS total_profit,
        CASE
            WHEN COALESCE(cd.is_complete, true) THEN COALESCE(cd.dividends, (0)::numeric)
            ELSE NULL::numeric
        END AS dividends,
        CASE
            WHEN COALESCE(cd.is_complete, true) THEN COALESCE(cd.withholding_tax, (0)::numeric)
            ELSE NULL::numeric
        END AS withholding_tax,
    COALESCE(lp.total_volume, (0)::numeric) AS total_volume,
        CASE
            WHEN COALESCE(lp.is_complete, true) THEN COALESCE(lp.cost_basis, (0)::numeric)
            ELSE NULL::numeric
        END AS cost_basis,
        CASE
            WHEN COALESCE(lp.is_complete, true) THEN COALESCE(lp.market_value, (0)::numeric)
            ELSE NULL::numeric
        END AS market_value,
    ((COALESCE(lp.missing_fx_count, (0)::bigint) + COALESCE(cp.missing_fx_count, (0)::bigint)) + COALESCE(cd.missing_fx_count, (0)::bigint)) AS missing_fx_count,
    (COALESCE(lp.is_complete, true) AND COALESCE(cp.is_complete, true) AND COALESCE(cd.is_complete, true)) AS is_complete,
    now() AS updated_at
   FROM (((latest_positions lp
     FULL JOIN closed_positions cp ON (((cp.portfolio_id = lp.portfolio_id) AND (cp.asset_id = lp.asset_id))))
     FULL JOIN cash_dividends cd ON (((cd.portfolio_id = COALESCE(lp.portfolio_id, cp.portfolio_id)) AND (cd.asset_id = COALESCE(lp.asset_id, cp.asset_id)))))
     JOIN investory.assets asset ON ((asset.id = COALESCE(lp.asset_id, cp.asset_id, cd.asset_id))))
  WITH NO DATA;


--
-- Name: app_v_symbol_performance; Type: VIEW; Schema: investory; Owner: -
--

CREATE VIEW investory.app_v_symbol_performance AS
 SELECT portfolio_id,
    symbol,
    asset_id,
    investory.application_display_value(closed_profit) AS closed_profit,
    investory.application_display_value(unrealized_profit) AS unrealized_profit,
    investory.application_display_value(total_profit) AS total_profit,
    investory.application_display_value(dividends) AS dividends,
    investory.application_display_value(withholding_tax) AS withholding_tax,
    total_volume,
    investory.application_display_value(cost_basis) AS cost_basis,
    investory.application_display_value(market_value) AS market_value,
    missing_fx_count,
    is_complete,
    updated_at
   FROM investory.symbol_performance src;


--
-- Name: VIEW app_v_symbol_performance; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON VIEW investory.app_v_symbol_performance IS 'Application-facing derived view. Compatibility source: investory.symbol_performance';


--
-- Name: asset_source_symbols; Type: TABLE; Schema: investory; Owner: -
--

CREATE TABLE investory.asset_source_symbols (
    id bigint NOT NULL,
    asset_id bigint NOT NULL,
    source character varying(32) NOT NULL,
    source_symbol character varying(64) NOT NULL,
    source_market character varying(32),
    price_currency character varying(3) NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    xtb_symbol character varying(64),
    match_method character varying(64),
    match_status character varying(64),
    confidence character varying(32),
    is_exact_listing boolean DEFAULT false NOT NULL,
    is_alternate_listing boolean DEFAULT false NOT NULL,
    original_exchange character varying(32),
    matched_exchange character varying(32),
    original_currency character varying(3),
    matched_currency character varying(3),
    requires_fx_conversion boolean DEFAULT false NOT NULL,
    price_scale_factor numeric(20,8) DEFAULT 1 NOT NULL,
    scale_reason character varying(255),
    scale_confidence character varying(32),
    scale_observation_count integer,
    scale_median_ratio numeric(20,8),
    scale_dispersion numeric(20,8),
    manual_approval_status character varying(32) DEFAULT 'UNREVIEWED'::character varying NOT NULL,
    substitution_reason character varying(511),
    CONSTRAINT chk_asset_source_symbols_price_scale_factor_positive CHECK ((price_scale_factor > (0)::numeric)),
    CONSTRAINT chk_asset_source_symbols_scale_observation_count_non_negative CHECK (((scale_observation_count IS NULL) OR (scale_observation_count >= 0))),
    CONSTRAINT chk_asset_source_symbols_source_code CHECK (((source)::text ~ '^[A-Z][A-Z0-9_]{0,31}$'::text)),
    CONSTRAINT chk_asset_source_symbols_source_symbol_not_blank CHECK ((btrim((source_symbol)::text) <> ''::text))
);


--
-- Name: TABLE asset_source_symbols; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON TABLE investory.asset_source_symbols IS 'Explicit deterministic mapping between internal assets and provider/source symbols used for historical price imports.';


--
-- Name: COLUMN asset_source_symbols.source_symbol; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.source_symbol IS 'Provider-native symbol, for example STOOQ aapl.us or cdr.pl.';


--
-- Name: COLUMN asset_source_symbols.price_currency; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.price_currency IS 'Expected raw provider quote currency before any source-specific normalization. asset_price_history.price_currency records the currency of the stored valuation row.';


--
-- Name: COLUMN asset_source_symbols.match_method; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.match_method IS 'How the provider symbol was selected, for example EXACT_SYMBOL or MANUAL_ALTERNATE_LISTING.';


--
-- Name: COLUMN asset_source_symbols.match_status; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.match_status IS 'Validation status of the provider symbol mapping.';


--
-- Name: COLUMN asset_source_symbols.is_alternate_listing; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.is_alternate_listing IS 'True when provider data is a reviewed alternate listing proxy rather than exact exchange history.';


--
-- Name: COLUMN asset_source_symbols.requires_fx_conversion; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON COLUMN investory.asset_source_symbols.requires_fx_conversion IS 'True when this mapping intentionally supplies a quote in a currency different from assets.currency. Valuation always converts the selected row price_currency directly to its target.';


--
-- Name: asset_source_symbols_id_seq; Type: SEQUENCE; Schema: investory; Owner: -
--

CREATE SEQUENCE investory.asset_source_symbols_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: asset_source_symbols_id_seq; Type: SEQUENCE OWNED BY; Schema: investory; Owner: -
--

ALTER SEQUENCE investory.asset_source_symbols_id_seq OWNED BY investory.asset_source_symbols.id;


--
-- Name: asset_types; Type: TABLE; Schema: investory; Owner: -
