    expected_annual_growth_rate numeric(20,12) NOT NULL,
    CONSTRAINT ck_long_term_asset_valuation_growth CHECK (((expected_annual_growth_rate >= ('-1'::integer)::numeric) AND (expected_annual_growth_rate <= (1)::numeric))),
    CONSTRAINT long_term_asset_valuation_periods_check CHECK (((valid_to IS NULL) OR (valid_to >= valid_from)))
);


