    id bigint NOT NULL,
    portfolio_id bigint NOT NULL,
    name character varying(255) NOT NULL,
    asset_type character varying(32) NOT NULL,
    currency character varying(3) NOT NULL,
    external_key character varying(128),
    acquisition_date date,
    acquisition_value numeric(30,12),
    current_value numeric(30,12) NOT NULL,
    tax_base numeric(30,12),
    rental_tax_paid_by_tenant boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    archived_at date,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT long_term_assets_acquisition_value_check CHECK (((acquisition_value IS NULL) OR (acquisition_value >= (0)::numeric))),
    CONSTRAINT long_term_assets_asset_type_check CHECK (((asset_type)::text = ANY ((ARRAY['REAL_ESTATE'::character varying, 'BOND'::character varying, 'DEPOSIT'::character varying, 'CASH_RESERVE'::character varying, 'OTHER'::character varying])::text[]))),
    CONSTRAINT long_term_assets_current_value_check CHECK ((current_value >= (0)::numeric)),
    CONSTRAINT long_term_assets_name_check CHECK ((btrim((name)::text) <> ''::text)),
    CONSTRAINT long_term_assets_tax_base_check CHECK (((tax_base IS NULL) OR (tax_base >= (0)::numeric)))
);


