COMMENT ON VIEW investory.recon_v_asset_price_quality_issues IS 'Reconciliation or diagnostic view. Not an application input. Compatibility source: investory.reporting_asset_price_quality_issues';


--
-- Name: v_fx_reconciliation; Type: VIEW; Schema: investory; Owner: -
--

CREATE VIEW investory.v_fx_reconciliation AS
 WITH pairs AS (
         SELECT c1.id AS source_currency,
            c2.id AS target_currency
           FROM (investory.currencies c1
             CROSS JOIN investory.currencies c2)
          WHERE ((c1.id)::text <> (c2.id)::text)
        ), latest AS (
         SELECT DISTINCT ON (er.base, er.to_currency) er.base AS source_currency,
            er.to_currency AS target_currency,
            er.rate_date,
            er.source,
            er.method,
            er.rate
           FROM investory.exchange_rates er
          ORDER BY er.base, er.to_currency, er.rate_date DESC, er.imported_at DESC
        ), resolved AS (
         SELECT p.source_currency,
            p.target_currency,
            r_1.fx_rate_to_target,
            r_1.source_rate_date,
            r_1.rate_source,
            r_1.rate_method,
            r_1.age_days,
            r_1.conversion_status
           FROM (pairs p
             CROSS JOIN LATERAL investory.resolve_fx_rate(CURRENT_DATE, p.source_currency, p.target_currency) r_1(source_currency, target_currency, fx_rate_to_target, source, rate_method, rate_source, source_rate_date, age_days, conversion_status))
        )
 SELECT r.source_currency,
    r.target_currency,
    r.fx_rate_to_target,
    r.source_rate_date,
    r.rate_source,
    r.rate_method,
    r.age_days,
    r.conversion_status,
    l.rate AS latest_stored_rate,
    l.rate_date AS latest_stored_date,
    l.source AS latest_stored_source,
    l.method AS latest_stored_method,
    ( SELECT count(*) AS count
           FROM investory.exchange_rates e
          WHERE (((e.method)::text = 'INTERPOLATED'::text) AND ((e.base)::text = (r.source_currency)::text) AND ((e.to_currency)::text = (r.target_currency)::text))) AS interpolated_observation_count,
    ( SELECT count(*) AS count
           FROM investory.exchange_rates e
          WHERE ((e.method)::text = 'XTB_EXECUTION'::text)) AS xtb_execution_observation_count,
    ( SELECT count(*) AS count
           FROM investory.exchange_rates e
          WHERE ((e.method)::text = 'IBKR_EXECUTION'::text)) AS ibkr_execution_observation_count
   FROM (resolved r
     LEFT JOIN latest l ON ((((l.source_currency)::text = (r.source_currency)::text) AND ((l.target_currency)::text = (r.target_currency)::text))));


--
-- Name: VIEW v_fx_reconciliation; Type: COMMENT; Schema: investory; Owner: -
--

COMMENT ON VIEW investory.v_fx_reconciliation IS 'FX audit output: coverage, latest stored observation, resolver source/method/status, and broker observation counts.';


